arguments.new:
// covert a calendar object to a local timestamp (epoch, but with the offset baked in)
export function objToLocalTS(obj) {
  // for legacy reasons, Date.UTC interprets years between 0 and 99 as 19XX. 19XX has a
  // different leap-year structure than 0XX, which matters when the day overflows (e.g.
  // when adding days across February), so shift the year by 400 years -- a full
  // Gregorian cycle, so the leap-year structure is identical -- and shift it back after.
  const year = obj.year < 100 && obj.year >= 0 ? obj.year + 400 : obj.year;

  let d = Date.UTC(
    year,
    obj.month - 1,
    obj.day,
    obj.hour,
    obj.minute,
    obj.second,
    obj.millisecond
  );

  if (year !== obj.year) {
    d = new Date(d);
    d.setUTCFullYear(d.getUTCFullYear() - 400);
  }
  return +d;
}

arguments.old:
// covert a calendar object to a local timestamp (epoch, but with the offset baked in)
export function objToLocalTS(obj) {
  let d = Date.UTC(
    obj.year,
    obj.month - 1,
    obj.day,
    obj.hour,
    obj.minute,
    obj.second,
    obj.millisecond
  );

  // for legacy reasons, years between 0 and 99 are interpreted as 19XX; revert that
  if (obj.year < 100 && obj.year >= 0) {
    d = new Date(d);
    d.setUTCFullYear(d.getUTCFullYear() - 1900);
  }
  return +d;
}

